package com.postbird.mobile
import android.content.Context
import android.graphics.*
import android.util.Base64
import android.view.View
class PostBirdPngSceneView(context:Context):View(context){
 private val p=Paint(Paint.ANTI_ALIAS_FLAG or Paint.FILTER_BITMAP_FLAG or Paint.DITHER_FLAG)
 private val tp=Paint(Paint.ANTI_ALIAS_FLAG).apply{color=Color.rgb(45,56,70);textAlign=Paint.Align.CENTER;isFakeBoldText=true}
 private val bird=img(BIRD); private val eye=img(EYE); private val grass=img(GRASS); private val cloud=img(CLOUD); private val photo=img(PHOTO); private val video=img(VIDEO)
 override fun onDraw(c:Canvas){super.onDraw(c);val w=width.toFloat();val h=height.toFloat();val card=RectF(w*.065f,h*.025f,w*.935f,h*.975f);p.style=Paint.Style.FILL;p.color=Color.rgb(137,195,242);c.drawRoundRect(card,38f,38f,p);cl(c,card.left+card.width()*.20f,card.top+card.height()*.13f,.95f);cl(c,card.left+card.width()*.78f,card.top+card.height()*.13f,.92f);cl(c,card.left+card.width()*.24f,card.top+card.height()*.32f,.72f);cl(c,card.left+card.width()*.83f,card.top+card.height()*.31f,.76f);speech(c,card);c.drawBitmap(grass,null,RectF(card.left,card.top+card.height()*.57f,card.right,card.bottom),p);val bw=card.width()*.45f;val bh=bw*bird.height/bird.width;val bl=card.centerX()-bw*.5f;val bt=card.top+card.height()*.435f;val br=RectF(bl,bt,bl+bw,bt+bh);p.color=Color.argb(45,55,72,62);c.drawOval(RectF(card.centerX()-bw*.29f,br.bottom-bh*.055f,card.centerX()+bw*.30f,br.bottom-bh*.005f),p);c.drawBitmap(bird,null,br,p);val es=bw*.145f;c.drawBitmap(eye,null,RectF(bl+bw*.445f,bt+bh*.235f,bl+bw*.445f+es,bt+bh*.235f+es),p);env(c,photo,card.left+card.width()*.26f,card.bottom-card.height()*.13f);env(c,video,card.left+card.width()*.74f,card.bottom-card.height()*.13f)}
 private fun cl(c:Canvas,x:Float,y:Float,s:Float){val cw=92f*s;val ch=cw*cloud.height/cloud.width;c.drawBitmap(cloud,null,RectF(x-cw/2,y-ch/2,x+cw/2,y+ch/2),p)}
 private fun env(c:Canvas,b:Bitmap,x:Float,y:Float){val ew=126f;val eh=ew*b.height/b.width;c.drawBitmap(b,null,RectF(x-ew/2,y-eh/2,x+ew/2,y+eh/2),p)}
 private fun speech(c:Canvas,card:RectF){val b=RectF(card.left+card.width()*.19f,card.top+card.height()*.18f,card.right-card.width()*.19f,card.top+card.height()*.255f);p.color=Color.WHITE;c.drawRoundRect(b,42f,42f,p);val t=Path().apply{moveTo(b.centerX()-18f,b.bottom-2f);lineTo(b.centerX(),b.bottom+28f);lineTo(b.centerX()+18f,b.bottom-2f);close()};c.drawPath(t,p);tp.textSize=30f;c.drawText("选择要发送的文件吧！",b.centerX(),b.centerY()+10f,tp)}
 companion object{private fun img(s:String):Bitmap{val a=Base64.decode(s,Base64.NO_WRAP);return BitmapFactory.decodeByteArray(a,0,a.size)?:error("png decode failed")}
 private const val BIRD=""
 private const val EYE="iVBORw0KGgoAAAANSUhEUgAAAAkAAAAJCAYAAADgkQYQAAAATklEQVR42mNgIAIwovGZkNj/GMgBTAwMDAyCgoLWQkJCWwUFBa2QxZnQrLFhZmbyYmBgsMFiPQTIy8tziIiI2KmoqLCT7BZmLL5lJstXAKwvBPWfHVy7AAAAAElFTkSuQmCC"
 private const val GRASS=""
 private const val CLOUD=""
 private const val PHOTO=""
 private const val VIDEO=""
 }
}
